-- Never edit this file once it is deployed (the updater would run it and every later custom file again):
-- a later fix is a new file. Running it again changes nothing: see docs/forever-import.md.

CREATE TABLE IF NOT EXISTS `everlake_import_rows` (
  `tbl` varchar(64) NOT NULL COMMENT 'world table of the row',
  `k1` bigint NOT NULL COMMENT 'the row''s key, in the table''s primary key order',
  `k2` bigint NOT NULL DEFAULT '0',
  `k3` bigint NOT NULL DEFAULT '0',
  `k4` bigint NOT NULL DEFAULT '0',
  `file` varchar(200) NOT NULL COMMENT 'the update file that added the row',
  `note` varchar(255) NOT NULL DEFAULT '' COMMENT 'the sources that gave it',
  PRIMARY KEY (`tbl`, `k1`, `k2`, `k3`, `k4`),
  KEY `file` (`file`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Rows the Everlake world import added (docs/forever-import.md)';

-- creature_template: NPCs the world has no template for (never again once added: one the fork removes stays removed)
DROP TEMPORARY TABLE IF EXISTS `everlake_import_stage`;
CREATE TEMPORARY TABLE `everlake_import_stage` (`entry` int unsigned NOT NULL, `KillCredit1` int unsigned NOT NULL, `KillCredit2` int unsigned NOT NULL, `name` mediumtext, `femaleName` mediumtext, `subname` mediumtext, `TitleAlt` mediumtext, `IconName` varchar(64), `RequiredExpansion` int NOT NULL, `VignetteID` int NOT NULL, `faction` smallint unsigned NOT NULL, `npcflag` bigint unsigned NOT NULL, `speed_walk` float NOT NULL, `speed_run` float NOT NULL, `scale` float NOT NULL, `Classification` tinyint unsigned NOT NULL, `dmgschool` tinyint NOT NULL, `BaseAttackTime` int unsigned NOT NULL, `RangeAttackTime` int unsigned NOT NULL, `BaseVariance` float NOT NULL, `RangeVariance` float NOT NULL, `unit_class` tinyint unsigned NOT NULL, `unit_flags` int unsigned NOT NULL, `unit_flags2` int unsigned NOT NULL, `unit_flags3` int unsigned NOT NULL, `family` int NOT NULL, `trainer_class` tinyint unsigned NOT NULL, `type` tinyint unsigned NOT NULL, `VehicleId` int unsigned NOT NULL, `AIName` varchar(64) NOT NULL, `MovementType` tinyint unsigned NOT NULL, `ExperienceModifier` float NOT NULL, `RacialLeader` tinyint unsigned NOT NULL, `movementId` int unsigned NOT NULL, `WidgetSetID` int NOT NULL, `WidgetSetUnitConditionID` int NOT NULL, `RegenHealth` tinyint unsigned NOT NULL, `CreatureImmunitiesId` int NOT NULL, `flags_extra` int unsigned NOT NULL, `ScriptName` varchar(64) NOT NULL, `StringId` varchar(64), `VerifiedBuild` int NOT NULL, `note` varchar(255) NOT NULL, `missing` tinyint NOT NULL DEFAULT '0', PRIMARY KEY (`entry`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
UPDATE `everlake_import_stage` s SET s.`missing` = 1 WHERE NOT EXISTS (SELECT 1 FROM `creature_template` t WHERE t.`entry` = s.`entry`) AND NOT EXISTS (SELECT 1 FROM `everlake_import_rows` r WHERE r.`tbl` = 'creature_template' AND r.`k1` = s.`entry`);
DROP TEMPORARY TABLE `everlake_import_stage`;

