-- creature: spawns of the new NPCs at points a live sighting confirms (not where the fork spawns the NPC within 40 yards)
DROP TEMPORARY TABLE IF EXISTS `everlake_import_stage`;
CREATE TEMPORARY TABLE `everlake_import_stage` (`guid` bigint unsigned NOT NULL, `id` int unsigned NOT NULL, `map` smallint unsigned NOT NULL, `zoneId` smallint unsigned NOT NULL, `areaId` smallint unsigned NOT NULL, `spawnDifficulties` varchar(100) NOT NULL, `phaseUseFlags` tinyint unsigned NOT NULL, `PhaseId` int, `PhaseGroup` int, `terrainSwapMap` int NOT NULL, `modelid` int unsigned NOT NULL, `equipment_id` tinyint NOT NULL, `position_x` float NOT NULL, `position_y` float NOT NULL, `position_z` float NOT NULL, `orientation` float NOT NULL, `spawntimesecs` int unsigned NOT NULL, `wander_distance` float NOT NULL, `currentwaypoint` int unsigned NOT NULL, `MovementType` tinyint unsigned NOT NULL, `VerifiedBuild` int NOT NULL, `note` varchar(255) NOT NULL, `missing` tinyint NOT NULL DEFAULT '0', PRIMARY KEY (`guid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
UPDATE `everlake_import_stage` s SET s.`missing` = 1 WHERE NOT EXISTS (SELECT 1 FROM `creature` t WHERE t.`guid` = s.`guid`) AND NOT EXISTS (SELECT 1 FROM `everlake_import_rows` r WHERE r.`tbl` = 'creature' AND r.`k1` = s.`guid`) AND EXISTS (SELECT 1 FROM `everlake_import_rows` t0 JOIN `creature_template` c0 ON c0.`entry` = t0.`k1` WHERE t0.`tbl` = 'creature_template' AND t0.`k1` = s.`id` AND t0.`file` = '2026_11_08_06_world_everlake_import_slice5.sql' AND c0.`VerifiedBuild` = 0) AND NOT EXISTS (SELECT 1 FROM `creature` c WHERE c.`id` = s.`id` AND c.`map` = s.`map` AND (c.`position_x` - s.`position_x`) * (c.`position_x` - s.`position_x`) + (c.`position_y` - s.`position_y`) * (c.`position_y` - s.`position_y`) <= 1600 AND NOT EXISTS (SELECT 1 FROM `everlake_import_rows` o WHERE o.`tbl` = 'creature' AND o.`k1` = c.`guid`));
DROP TEMPORARY TABLE `everlake_import_stage`;

